-- ADR 0036 (2026-10-12), Phase 0: P4 (one lead agent per listing) and P7 (indexes
-- for figures). The first block is hand-written (a data repair, not in the
-- drizzle snapshot); the three indexes are generated by drizzle-kit.
--
-- P4 repair, BEFORE the unique index (decided by the user): a listing with more
-- than one listing_agent row at display_order 0 has ALL its rows renumbered
-- 0, 1, 2… by (display_order, created_at, user_id) — the oldest assignment
-- keeps 0, the other former zeros follow it, and rows already at 1, 2… keep
-- their order behind them. Listings with one row at 0 are not touched. A row
-- moved OFF 0 also becomes role 'co' (decided by the user): it is no longer
-- the primary agent, so only the row kept at 0 may still say 'lead'. Rows that
-- were already at 1, 2… keep their role. Dry run (what would change):
--   select listing_id, count(*) from listing_agent where display_order = 0
--   group by listing_id having count(*) > 1;
WITH dup AS (
	SELECT listing_id FROM listing_agent WHERE display_order = 0
	GROUP BY listing_id HAVING count(*) > 1
), renumbered AS (
	SELECT la.listing_id, la.user_id,
	       (row_number() OVER (PARTITION BY la.listing_id ORDER BY la.display_order, la.created_at, la.user_id) - 1)::integer AS n
	FROM listing_agent la JOIN dup ON dup.listing_id = la.listing_id
)
UPDATE listing_agent la
SET display_order = r.n,
    -- SET reads the row as it was: a former 0 moving up is no longer the lead.
    role = CASE WHEN la.display_order = 0 AND r.n > 0 THEN 'co'::listing_agent_role ELSE la.role END,
    updated_at = now()
FROM renumbered r
WHERE la.listing_id = r.listing_id AND la.user_id = r.user_id AND la.display_order <> r.n;--> statement-breakpoint
CREATE UNIQUE INDEX "listing_agent_lead_idx" ON "listing_agent" USING btree ("listing_id") WHERE display_order = 0;--> statement-breakpoint
CREATE INDEX "listing_agency_status_sold_idx" ON "listing" USING btree ("agency_id","status","sold_date");--> statement-breakpoint
CREATE INDEX "mail_message_agency_created_idx" ON "mail_message" USING btree ("agency_id","created_at");
